scwin.img_ISU_CD_onclick = async function() {
    try {
        if (scwin.vIsurCd === "") {
            await $c.win.alert("[회사]를 선택하세요.");
            return;
        }
        scwin.getPar = scwin.getParIsuCd;
        scwin.setPar = scwin.setParIsuCd;
        $c.lc.fn_PopFindIsuOfIsur();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05711.img_ISU_CD_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        scwin.parentRefresh(); // 목록 다시 조회
        if (scwin.TR_JOB === 'D') {
            await $c.win.closePopup();
        } else {
            await scwin.readSync();
            buttonSet.setUpdateStatus();

            // 코스닥일때 보임
            if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "1") {
                btn_Print.hide();
            } else {
                if (scwin.vOpenTyp === "R" && scwin.vBzProcsNo === "") {
                    btn_Print.hide();
                } else {
                    btn_Print.show("");
                }
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05711.trs_Save_OnSuccess" });
    }
};

