 */
scwin.getBfIsuReadSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05711.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_CHG_ISS_SW_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL2 + "&ISU_CD=" + txb_ISU_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_Bf_Isu",
        action : "/Listing.do",
        ref : "",
        target : "dts_Bf_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    edt_BFCHG_LIST_SHRS.setValue(dts_Bf_Isu.getCellData(1, "LIST_SHRS"));
};

