/**
 * @method
 * @name calcuate
 * @description calcuate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcuate = async function() {
    try {
        let vsum = parseInt(edt_BFCHG_LIST_SHRS.getValue()) + parseInt(edt_INCDEC_LIST_SHRS.getValue());
        edt_LIST_SHRS.setValue(vsum);
        // 변경후 상장 증권수량과 발행주식수는 같음
        edt_ISU_SHRS.setValue(vsum);
        await scwin.calcuate2();
    } catch (err) {
        await $c.win.alert("[증권수 합산처리 중  오류]");
    }
};

/**
 * @method
 * @name calcuate2
 * @description calcuate2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcuate2 = async function() {
    try {
        // 발행가액 총액 구함.
        let vsum = parseInt(edt_ISU_SHRS.getValue()) * parseInt(edt_EXER_PRC.getValue());
        edt_TOT_ISU_PRC.setValue(vsum);
    } catch (err) {
        await $c.win.alert("[증권수 합산처리 중  오류]");
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }
    if (edt_ISU_DD.getValue() === "") {
        await $c.win.alert("[발행일]을 입력하세요.");
        edt_ISU_DD.focus();
        return false;
    }
    if (edt_LIST_DD.getValue() === "") {
        await $c.win.alert("[상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (vCurDate >= edt_LIST_DD.getValue()) {
        await $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (edt_EXER_STRT_DD.getValue() === "") {
        await $c.win.alert("[행사시작일]을 입력하세요.");
        edt_EXER_STRT_DD.focus();
        return false;
    }
    if (edt_EXER_END_DD.getValue() === "") {
        await $c.win.alert("[행사종료일]을 입력하세요.");
        edt_EXER_END_DD.focus();
        return false;
    }
    if (parseInt(edt_EXER_STRT_DD.getValue(), 10) >= parseInt(edt_EXER_END_DD.getValue(), 10)) {
        await $c.win.alert("[행사시작일]은 [행사종료일]보다 작아야 합니다. 다시 입력해주세요");
        return false;
    }
    if (cmb_LIST_METHD_TP_CD.getValue() === "") {
        await $c.win.alert("[상장방식]을 선택하세요.");
        cmb_LIST_METHD_TP_CD.focus();
        return false;
    }
    if (edt_INCDEC_LIST_SHRS.getValue() === "") {
        await $c.win.alert("[증감증권수량]을 입력하세요.");
        edt_INCDEC_LIST_SHRS.focus();
        return false;
    }
    if (edt_INCDEC_LIST_SHRS.getValue() === 0) {
        await $c.win.alert("[증감증권수량]을 입력하세요.");
        edt_INCDEC_LIST_SHRS.focus();
        return false;
    }

    // if (! fn_checkNumber(edt_INCDEC_LIST_SHRS, '증감증권수량')) return false;  //- 값이 들오와서 주석처리 (2009.04.03)

    if (edt_ISU_SHRS.getValue() === "") {
        await $c.win.alert("[발행주식수]을 입력하세요.");
        edt_ISU_SHRS.focus();
        return false;
    }
    // if (! fn_checkNumber(edt_ISU_SHRS, '발행주식수')) return false;

    if (edt_EXER_PRC.getValue() === "") {
        await $c.win.alert("[행사가격]을 입력하세요.");
        edt_EXER_PRC.focus();
        return false;
    }
    // if (! fn_checkNumber(edt_EXER_PRC, '행사가격')) return false;

    if (edt_TOT_ISU_PRC.getValue() === "") {
        await $c.win.alert("[발행가액총액]을 입력하세요.");
        edt_TOT_ISU_PRC.focus();
        return false;
    }
    // if (! fn_checkNumber(edt_TOT_ISU_PRC, '발행가액총액')) return false;

    if (txb_ISU_RSN_CONTN.getValue() === "") {
        await $c.win.alert("[변경사유]를 입력하세요.");
        txb_ISU_RSN_CONTN.focus();
        return false;
    }
    if (txb_SUBSRGHT_CONTN.getValue() === "") {
        await $c.win.alert("[신주인수권의 내용]를 입력하세요.");
        txb_SUBSRGHT_CONTN.focus();
        return false;
    }
    if (txb_SUBSRGHT_EXERTM_PAYMETHD_CONTN.getValue() === "") {
        await $c.win.alert("[신주의 납입방법]를 입력하세요.");
        txb_SUBSRGHT_EXERTM_PAYMETHD_CONTN.focus();
        return false;
    }
    /* 2009-04-24  신주인수권증권 변경상장 중복입력체크 */
    /*행사일이 다르고 상장일이 같을 수 있으므로 중복입력 체크는 하지 않는다.*/
    /*if (! fn_check_bz_doubleinput(	dts_BZ_CHECK,
    												getObjectValue(txb_ISU_CD),
    												getObjectValue(edt_LIST_DD),
    												vBzProcsNo,
    												LIST_BZ_TP_CD_144)) {
    	return false;
    }
     */

    return true;
};

/**
 * @method
 * @name checkNumber
 * @description check Number 처리
 * @param {Object} obj 컴포넌트
 * @param {String} str str
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkNumber = async function(obj, str) {
    if (obj.getValue() <= 100) {
        await $c.win.alert("[" + str + "]를 '" + obj.getValue() + "'으로 입력하셨습니다. 확인 후 재입력바랍니다.");
        obj.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        if (scwin.vAcptNo === "") {
            scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        }
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            // dts_Isu.UserStatus(1) = TB_JOB_INSERT;
            dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            await scwin.trs(TRS_IDX_INSERT);
        }
    }
};

