/**
 * @method
 * @name setNPARVALSTKYNEvent
 * @description set NPARVALSTKYNEvent 처리
 * @returns {void}
 * @hidden N
 */
scwin.setNPARVALSTKYNEvent = function() {
    if (chk_NPARVALSTK_YN.checked) {
        edt_EXER_PRC.setReadOnly(true);
        edt_EXER_PRC.ReadOnlyBackColor = '#b9d4f7';
        edt_EXER_PRC.setValue('');
        edt_PER1STK_CAP.setReadOnly(false);
        edt_PER1STK_CAP.ReadOnlyBackColor = '#ffffff';
    } else {
        edt_EXER_PRC.setReadOnly(false);
        edt_EXER_PRC.ReadOnlyBackColor = '#ffffff';
        edt_PER1STK_CAP.setReadOnly(true);
        edt_PER1STK_CAP.ReadOnlyBackColor = '#b9d4f7';
        edt_PER1STK_CAP.setValue('');
    }
};

/**
 * @method
 * @name getCheckboxData
 * @description get Checkbox Data 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getCheckboxData = function(obj) {
    if (obj.checked) {
        return 'Y';
    } else {
        return 'N';
    }
};
